const command = COMMANDS.find((entry) => entry.id === 'escape')!;
let currentOverlay: unknown = value.overlay;
let selectionAfter: unknown = value.selection;
const setOverlay = (next: unknown): void => {
  currentOverlay = next;
};
const setSelection = (next: unknown): void => {
  selectionAfter = next;
};
const context = {
  ui: {
    overlay: (): unknown => currentOverlay,
    setOverlay,
    selection: (): unknown => value.selection,
    setSelection,
  },
} as unknown as Parameters<typeof command.run>[0];

command.run(context);
expect(currentOverlay).toBeUndefined();
expect(selectionAfter).toEqual(value.selection);

