helpers.expectedChord:
function expectedChord(platform: string, chord: { key: string; meta?: boolean; shift?: boolean }): string {
  let key: string;
  switch (chord.key) {
    case 'ArrowUp': key = 'Up'; break;
    case 'ArrowDown': key = 'Down'; break;
    case 'ArrowLeft': key = 'Left'; break;
    case 'ArrowRight': key = 'Right'; break;
    case 'Escape': key = 'Esc'; break;
    default: key = chord.key.length === 1 ? chord.key.toUpperCase() : chord.key;
  }
  if (platform.includes('Mac')) {
    return (chord.meta ? '⌘' : '') + (chord.shift ? '⇧' : '') + key;
  }
  return (chord.meta ? 'Ctrl+' : '') + (chord.shift ? 'Shift+' : '') + key;
}

helpers.setNavigator:
function setNavigator(platform: string, userAgent: string): void {
  Object.defineProperty(navigator, 'platform', { configurable: true, value: platform });
  Object.defineProperty(navigator, 'userAgent', { configurable: true, value: userAgent });
}

