helpers.makeCommand:
function makeCommand(id: string, label: string): { id: never; label: string; run: (context: unknown) => void } {
  return { id: id as never, label, run: (_context: unknown): void => {} };
}

helpers.makeKeymap:
function makeKeymap(command: string, key: string): { command: never; chord: never } {
  return { command: command as never, chord: { key, metaKey: false, shiftKey: false } as never };
}

