mixed-element-collections.body:
const diagram = makeDiagram();
let expectedKeys: string[] = [];
if (parts.node) { diagram.nodes.node = { id: 'node', label: [] }; expectedKeys.push('node:node'); }
if (parts.group) { diagram.groups.group = { id: 'group', label: [] }; expectedKeys.push('group:group'); }
if (parts.annotation) { diagram.annotations.annotation = { id: 'annotation', content: [] }; expectedKeys.push('annotation:annotation'); }
for (let index = 0; index < parts.edges; index += 1) diagram.edges[`edge-${index}`] = { id: `edge-${index}` };
const rows = elementPaletteItems(diagram);
expect(rows.map((row) => row.key)).toEqual(expectedKeys.sort());

